/// Emits the inline JavaScript that polls `/challenge/{name}/instance-state`
/// every 5 seconds and counts down the timer locally every second.
pub fn instance_live_script(challenge_name: &str) -> String {
    let endpoint = format!(
        "/challenge/{}/instance-state",
        urlencoding::encode(challenge_name),
    );

    format!(
        r#"(function(){{const endpoint='{endpoint}';const statusEl=document.getElementById('instance-status');const timerEl=document.getElementById('instance-timer');const extendEl=document.getElementById('extend-form');let lastState=null;let localSeconds=null;function fmt(s){{const h=Math.floor(s/3600);const m=Math.floor((s%3600)/60);const sec=s%60;if(h>0)return`${{h}}h ${{m}}m ${{sec}}s`;if(m>0)return`${{m}}m ${{sec}}s`;return`${{sec}}s`;}}function setStatus(state){{if(!statusEl)return;if(state.solved){{statusEl.textContent='This challenge is solved. Instance is stopped and submissions are disabled.';return;}}if(!state.has_instance){{statusEl.textContent='No active instance. Spawn to start the challenge.';return;}}if(!state.ready){{if(typeof state.time_left_seconds==='number'&&state.time_left_seconds===0){{statusEl.textContent='Instance expired. Spawn a new one to continue.';}}else{{statusEl.textContent='Instance is starting. This page updates automatically when it is ready.';}}return;}}statusEl.textContent='Instance is ready.';}}function tick(){{if(localSeconds===null)return;localSeconds=Math.max(0,localSeconds-1);if(timerEl)timerEl.textContent='Time left: '+fmt(localSeconds);if(extendEl)extendEl.style.display=(localSeconds<=300&&localSeconds>0)?'block':'none';}}async function poll(){{try{{const res=await fetch(endpoint,{{credentials:'same-origin',cache:'no-store'}});if(!res.ok)return;const state=await res.json();setStatus(state);const key=`${{state.solved}}|${{state.has_instance}}|${{state.ready}}|${{state.instance_name||''}}`;if(lastState!==null&&key!==lastState){{window.location.reload();return;}}lastState=key;if(state.solved){{localSeconds=null;if(timerEl)timerEl.textContent='';if(extendEl)extendEl.style.display='none';return;}}if(!state.has_instance){{localSeconds=null;if(timerEl)timerEl.textContent='';if(extendEl)extendEl.style.display='none';return;}}if(typeof state.time_left_seconds==='number'){{localSeconds=state.time_left_seconds;if(timerEl)timerEl.textContent='Time left: '+fmt(localSeconds);}}else{{localSeconds=null;if(timerEl)timerEl.textContent='';}}if(extendEl)extendEl.style.display=state.can_extend?'block':'none';}}catch(_err){{}}}}setInterval(tick,1000);setInterval(poll,5000);poll();}})();"#,
    )
}
